"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def HAS_CYCLE(head):
    tortoise = head
    hare = head
    while (((tortoise is not None) and (hare is not None)) and (hare.next is not None)):
        tortoise = tortoise.next
        hare = hare.next.next
        if (tortoise == hare):
            return True
    return False
